<?php $footer=footerSettings();function footerLinkRow(array $link=[]): void {?>
<div class="footer-link-row"><label><?=e(t('Text'))?><input name="footer_label[]" maxlength="80" value="<?=e($link['label']??'')?>"></label><label><?=e(t('URL (optional)'))?><input name="footer_url[]" maxlength="1000" value="<?=e($link['url']??'')?>" placeholder="<?=e(t('Empty means plain text'))?>"></label><div class="menu-order"><button class="text-button" type="button" data-up aria-label="<?=e(t('Move up'))?>">↑</button><button class="text-button" type="button" data-down aria-label="<?=e(t('Move down'))?>">↓</button><button class="text-button" type="button" data-remove><?=e(t('Remove'))?></button></div></div>
<?php } ?>
<section class="panel admin-panel"><h2><?=e(t('Footer settings'))?></h2><form class="footer-settings-form" data-admin-action="footer_save" data-stay><label class="menu-visible"><input type="checkbox" name="show_name" value="1" <?=$footer['show_name']?'checked':''?>><?=e(t('Show site name'))?></label><label class="menu-visible"><input type="checkbox" name="show_description" value="1" <?=$footer['show_description']?'checked':''?>><?=e(t('Show site description'))?></label><label><?=e(t('Copyright text'))?><textarea name="copyright" rows="3" maxlength="500"><?=e($footer['copyright'])?></textarea></label><h3><?=e(t('Footer links'))?></h3><div id="footer-links-editor"><?php foreach($footer['links'] as $link)footerLinkRow($link);?></div><div class="admin-row-actions"><button type="button" class="text-button" id="add-footer-link"><?=e(t('Add link'))?></button><button type="submit" class="button"><?=e(t('Save footer'))?></button></div><p role="status"></p></form><template id="footer-link-template"><?php footerLinkRow();?></template></section>
